sys_script_include.script:
var CampusMatchAccess = Class.create();

CampusMatchAccess.prototype = {

    initialize: function() {
    },


    /* =========================================
       STAFF ACCESS
    ========================================= */

    isStaff: function() {

        return (
            gs.hasRole('x_snc_campusmatch.staff') ||
            gs.hasRole('admin')
        );

    },


    /* =========================================
       CURRENT USER
    ========================================= */

    getUserId: function() {

        return gs.getUserID();

    },


    /* =========================================
       ITEM OWNER
    ========================================= */

    ownsItem: function(item) {

        if (!item) {
            return false;
        }

        return (
            item.getValue('reporter') ===
            gs.getUserID()
        );

    },


    /* =========================================
       MATCH PARTICIPANT
    ========================================= */

    canViewMatch: function(lostItem, foundItem) {

        if (this.isStaff()) {
            return true;
        }

        if (!lostItem || !foundItem) {
            return false;
        }

        var userId =
            gs.getUserID();

        return (
            lostItem.getValue('reporter') === userId ||
            foundItem.getValue('reporter') === userId
        );

    },


    type: 'CampusMatchAccess'
};
